import React, { useState } from "react";
import { DndProvider, useDrag, useDrop } from "react-dnd";
import { HTML5Backend } from "react-dnd-html5-backend";
import { PlusCircle, CheckCircle, Circle, Trash2, Play, StopCircle } from "lucide-react";
import "./App.css";

function App() {
  const [tasks, setTasks] = useState([]);
  const [taskInputs, setTaskInputs] = useState({ 1: "", 2: "", 3: "", 4: "" });

  const addTask = (quadrant) => {
    if (!taskInputs[quadrant].trim()) return;
    const newTask = {
      id: Date.now(),
      text: taskInputs[quadrant],
      quadrant,
      completed: false,
      dueDate: null,
      timer: 0,
      isRunning: false,
    };
    setTasks([...tasks, newTask]);
    setTaskInputs({ ...taskInputs, [quadrant]: "" });
  };

  const moveTask = (taskId, newQuadrant) => {
    setTasks(tasks.map((task) => (task.id === taskId ? { ...task, quadrant: newQuadrant } : task)));
  };

  const setTaskDueDate = (taskId, dueDate) => {
    setTasks(tasks.map((task) => (task.id === taskId ? { ...task, dueDate } : task)));
  };

  const toggleTaskCompletion = (taskId) => {
    setTasks(tasks.map((task) => (task.id === taskId ? { ...task, completed: !task.completed } : task)));
  };

  const deleteTask = (taskId) => {
    setTasks(tasks.filter((task) => task.id !== taskId));
  };

  const toggleTaskTimer = (taskId) => {
    setTasks(
      tasks.map((task) =>
        task.id === taskId ? { ...task, isRunning: !task.isRunning } : task
      )
    );
  };

  const updateTaskTimer = (taskId) => {
    setTasks(
      tasks.map((task) =>
        task.id === taskId && task.isRunning ? { ...task, timer: task.timer + 1 } : task
      )
    );
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="App">
        <table className="matrix-table">
          <thead>
            <tr>
              <th colSpan="3" className="matrix-title">
                Eisenhower Matrix
              </th>
            </tr>
            <tr>
              <th></th>
              <th className="urgent-header">Urgent</th>
              <th className="not-urgent-header">Not Urgent</th>
            </tr>
          </thead>
          <tbody>
            {[
              [1, 2],
              [3, 4],
            ].map((row, rowIndex) => (
              <tr key={rowIndex}>
                <th className={rowIndex === 0 ? "important-header" : "not-important-header"}>
                  {rowIndex === 0 ? "Important" : "Not Important"}
                </th>
                {row.map((quadrant) => (
                  <Quadrant
                    key={quadrant}
                    quadrant={quadrant}
                    tasks={tasks}
                    addTask={addTask}
                    moveTask={moveTask}
                    setTaskDueDate={setTaskDueDate}
                    toggleTaskCompletion={toggleTaskCompletion}
                    deleteTask={deleteTask}
                    toggleTaskTimer={toggleTaskTimer}
                    updateTaskTimer={updateTaskTimer}
                    taskInputs={taskInputs}
                    setTaskInputs={setTaskInputs}
                  />
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </DndProvider>
  );
}

function Quadrant({
  quadrant,
  tasks,
  addTask,
  moveTask,
  setTaskDueDate,
  toggleTaskCompletion,
  deleteTask,
  toggleTaskTimer,
  updateTaskTimer,
  taskInputs,
  setTaskInputs,
}) {
  const [{ isOver }, drop] = useDrop(() => ({
    accept: "TASK",
    drop: (item) => moveTask(item.id, quadrant),
    collect: (monitor) => ({ isOver: !!monitor.isOver() }),
  }));

  const handleInputChange = (quadrant, value) => {
    setTaskInputs({ ...taskInputs, [quadrant]: value });
  };

  return (
    <td ref={drop} className={`quadrant ${isOver ? "highlight" : ""}`}>
      <div className="task-input">
        <input
          type="text"
          placeholder="Enter Task"
          value={taskInputs[quadrant]}
          onChange={(e) => handleInputChange(quadrant, e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && addTask(quadrant)}
        />
        <PlusCircle className="add-icon" onClick={() => addTask(quadrant)} />
      </div>
      <TaskList
        quadrant={quadrant}
        tasks={tasks}
        setTaskDueDate={setTaskDueDate}
        toggleTaskCompletion={toggleTaskCompletion}
        deleteTask={deleteTask}
        toggleTaskTimer={toggleTaskTimer}
        updateTaskTimer={updateTaskTimer}
      />
    </td>
  );
}

function TaskList({
  quadrant,
  tasks,
  setTaskDueDate,
  toggleTaskCompletion,
  deleteTask,
  toggleTaskTimer,
  updateTaskTimer,
}) {
  const quadrantTasks = tasks.filter((task) => task.quadrant === quadrant);

  return (
    <div className="task-list">
      {quadrantTasks.map((task) => (
        <Task
          key={task.id}
          task={task}
          setTaskDueDate={setTaskDueDate}
          toggleTaskCompletion={toggleTaskCompletion}
          deleteTask={deleteTask}
          toggleTaskTimer={toggleTaskTimer}
          updateTaskTimer={updateTaskTimer}
        />
      ))}
    </div>
  );
}

function Task({
  task,
  setTaskDueDate,
  toggleTaskCompletion,
  deleteTask,
  toggleTaskTimer,
  updateTaskTimer,
}) {
  const [{ isDragging }, drag] = useDrag(() => ({
    type: "TASK",
    item: { id: task.id },
    collect: (monitor) => ({
      isDragging: !!monitor.isDragging(),
    }),
  }));

  return (
    <div
      ref={drag}
      className={`task ${isDragging ? "dragging" : ""} ${task.completed ? "completed" : ""}`}
    >
      <div className="task-content">
        <span onClick={() => toggleTaskCompletion(task.id)} className="task-checkbox">
          {task.completed ? <CheckCircle size={16} /> : <Circle size={16} />}
        </span>
        <span className="task-text">{task.text}</span>
        <span className="task-timer">{formatTime(task.timer)}</span>
        <span onClick={() => toggleTaskTimer(task.id)} className="task-start-icon">
          {task.isRunning ? <StopCircle size={16} /> : <Play size={16} />}
        </span>
        <span onClick={() => deleteTask(task.id)} className="task-delete-icon">
          <Trash2 size={16} />
        </span>
      </div>
      <input
        type="date"
        onChange={(e) => setTaskDueDate(task.id, e.target.value)}
        className="task-due-date"
      />
    </div>
  );
}

function formatTime(seconds) {
  const minutes = Math.floor(seconds / 60);
  const secs = seconds % 60;
  return `${minutes}:${secs < 10 ? "0" : ""}${secs}`;
}

export default App;
